import csv
import io


def parse_csv(raw_csv: str):
    expected_width = 7
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(csv.reader(
        io.StringIO(raw_csv, newline=""),
        delimiter=",",
        quotechar='"',
        doublequote=True,
    ))

    # Skip sparse preamble records, but retain all records after the header.
    header_index = next(
        (
            index
            for index, record in enumerate(records)
            if sum(bool(value.strip()) for value in record)
            >= (expected_width + 1) // 2
        ),
        None,
    )

    if header_index is None:
        columns = []
        rows = records
    else:
        columns = records[header_index]
        rows = records[header_index + 1:]

    width = max(expected_width, len(columns), max(map(len, rows), default=0))
    used_names = set(columns)
    for position in range(len(columns) + 1, width + 1):
        base = f"column_{position}"
        name = base
        suffix = 2
        while name in used_names:
            name = f"{base}_{suffix}"
            suffix += 1
        columns.append(name)
        used_names.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
